// === Tab: mySketch.js ===
//day 1
//me: The challenge theme this week is 'sparkles'. Rolls eyes.
//wife: You know, no one is making you do it.
//me: I know.

//day 2
//Me, to self: Plenty of things in nature sparkle, get over yourself.
//Codes a fairly convincing representation of sparkling water, with pixel array noise.
//Realizes it's going to have to be the size of postage stamp in order to run at a fameRate above
//single digits. Sighs and mutters (yet again) about the need to learn shaders.


//day 3
//F this. I'll just write a sparkle particle class and THEN figure out what to do with it.
//I do not figure out what to do with it.


//day 4
//Wake up to snow falling.
//Oh. Ok.
//Codes. Kind of good.
//But also kind of sappy pap.
//shrugs

sparkles=[]
let n1, n2, n3, n4
let simplex

function setup() {
	createCanvas(300, 600);
	simplex=new OpenSimplexNoise(Date.now())	
}

function preload(){
	me= loadImage('https://openprocessing.org/sketch/1849232/files/me.png')
}

function draw() {
	background(0);
	fill(20)
	rect(0, 0, width, height)

	//ground
	beginShape()
	fill(60)
	vertex(0, height)
	for(let x=0; x<=width; x+=1){
	let y=height*0.85+ (simplex.noise2D(x/100, height*0.75)*10)
	vertex(x, y	)											 	
	}
	vertex(width, height)
	endShape(CLOSE)

	//adding glitter particles 'snow'
	for(let i=0; i<1; i+=0.075){
	 let yPos=random(height)
	 let xPos=random(width)
	let pos= createVector(xPos+random(-5, 5), yPos+random(-50, 50))
	sparkles.push(new sparkle(pos))
	}


	for(let sparkle of sparkles){
		sparkle.live()
		sparkle.shinebriefly()
		sparkle.die()

	}

	//adding 'window'
noStroke()	
fill(0)
	rect(0, height/2, width, 30)

	//image of silhouette, slightly drifting, 
	//white-tinterd version offset from black tinted version 
	//image previously used in conceptual 'Autobigraphical Clock' :https://openprocessing.org/sketch/1340345
	push()
	translate(-width/3, height/5)
	tint(255, 100)
	moverX=simplex.noise2D(frameCount/100, 100)*2
	moverY= simplex.noise2D(frameCount/100, 200)*5
	image(me, -2, moverY)
	tint(0)
  image(me, moverX, moverY)
	pop()

}



class sparkle{
constructor(pos){
	this.pos=pos
	this.theta=-PI
}

live(){
	this.theta+=0.25
	let xMove= map(simplex.noise2D(this.pos.x/50, frameCount/50), -1, 1, -1, 1)
	let yMove= map(simplex.noise2D(this.pos.y/100, frameCount/50), -1, 1, 0, 2)
	let mover= createVector(xMove, yMove)
	this.pos.add(mover)
}

die(){
	if(this.theta>=PI){
		let index = sparkles.indexOf(this);
      sparkles.splice(index, 1);
	}

}

shinebriefly(){
	push()
	translate(this.pos.x, this.pos.y)
	let weight= map(sin(this.theta), -1, 1, 0.1, 5)
	stroke(255)
	strokeWeight(weight)
	point(0, 0)
	pop()

}	
}

